import{_ as d,o as e,c as o,a0 as c}from"./chunks/framework.Bmhw_dvp.js";const T=JSON.parse('{"title":"语音聊天链路","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/voice.md","filePath":"advanced/voice.md","lastUpdated":1793354613000}'),a={name:"advanced/voice.md"};function r(i,t,s,n,p,l){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="语音聊天链路" tabindex="-1">语音聊天链路 <a class="header-anchor" href="#语音聊天链路" aria-label="Permalink to &quot;语音聊天链路&quot;">​</a></h1><p>语音不参与播放同步，因此不走 Socket.IO，而是独立的实时音频链路。功能说明见<a href="/basic/features">功能说明</a>，端口映射见<a href="/basic/install">安装与部署</a>，变量清单见<a href="/advanced/env">环境变量</a>。</p><h2 id="音频由独立服务承载" tabindex="-1">音频由独立服务承载 <a class="header-anchor" href="#音频由独立服务承载" aria-label="Permalink to &quot;音频由独立服务承载&quot;">​</a></h2><p>实时音频交给 LiveKit（开源 WebRTC 实时通信服务），媒体形态为 SFU：每个客户端上传一份音频，服务端只转发不混流。</p><p>主后端不参与音频流转，只做三件事：签发接入凭证、执行禁言与踢出、代理信令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 ── POST /api/voice/token ──▶ 后端（3333）── 签发 AccessToken</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├─ 信令 wss://页面域名/rtc ──▶ 后端 /rtc 反代 ──▶ livekit-server（3336）</span></span>
<span class="line"><span>   └─ 媒体 RTP over UDP 3333 ──────────────▶ livekit-server</span></span>
<span class="line"><span>                  （UDP 被拦截时：ICE/TCP 3337 直连，或 TURN/TLS 3338 中继）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>端口</th><th>协议</th><th>用途</th></tr></thead><tbody><tr><td>3333</td><td>TCP</td><td>页面、REST API、Socket.IO，以及 <code>/rtc</code> 信令反代</td></tr><tr><td>3333</td><td>UDP</td><td>语音媒体（RTP）</td></tr><tr><td>3337</td><td>TCP</td><td>ICE/TCP 媒体直连（与 UDP 同时发布）</td></tr><tr><td>3336</td><td>TCP</td><td>livekit-server 的 HTTP 与信令端口，仅内部使用</td></tr><tr><td>3338</td><td>TCP</td><td>TURN/TLS 中继，UDP 被拦截时的兜底，需显式配置</td></tr></tbody></table><p>livekit-server 是独立的 Go 二进制（压缩后约 18 MB），不能编进主程序，因此以伴生进程随主进程启停。</p><table tabindex="0"><thead><tr><th>部署形态</th><th>二进制来源</th></tr></thead><tbody><tr><td>Windows 安装包</td><td><strong>不随包</strong>。第一次点「语音聊天」时下载到可执行文件旁，装好后立即拉起，不用重启</td></tr><tr><td>Linux 包 / Docker 镜像</td><td>随包内嵌（离线环境没有可靠的下载时机）</td></tr><tr><td>源码开发</td><td>缺失时自动下载到 <code>backend-go/dev-bin/</code></td></tr></tbody></table><p>Windows 端的下载源与桌面端可选组件一致：产物仓库 <code>ZviewerRelease</code> 的 <code>components</code> 分支，顺序为 GitCode 直链 → GitHub raw → 官方 Release。接口 <code>GET /api/voice/status</code> 报告可用性与进度，<code>POST /api/voice/install</code> 触发下载（需登录，服务端单飞去重）。组件未下载时 <code>/api/voice/token</code> 返回 503 并提示下载，前端在语音面板里把「加入语音」换成「下载语音聊天组件」。</p><h2 id="接入凭证" tabindex="-1">接入凭证 <a class="header-anchor" href="#接入凭证" aria-label="Permalink to &quot;接入凭证&quot;">​</a></h2><p>加入语音前先换令牌，接口 <code>POST /api/voice/token</code>（请求体带 <code>roomId</code> 与 <code>username</code>，需登录），这是连接 LiveKit 的唯一凭证。</p><p>ZViewer 房间映射为 LiveKit 房间，名为 <code>voice:&lt;roomId&gt;</code>，不同房间彼此隔离。令牌 grant 授予接入、发布、订阅与数据通道四项权限。</p><table tabindex="0"><thead><tr><th>身份</th><th>生成规则</th><th>重连行为</th></tr></thead><tbody><tr><td>登录用户</td><td><code>user:&lt;userId&gt;</code></td><td>身份稳定，重连后顶替自己上一条麦克风轨</td></tr><tr><td>游客</td><td><code>guest:&lt;时间戳36进制&gt;&lt;4位随机&gt;</code></td><td>每次加入都是新身份，不顶替他人</td></tr></tbody></table><p>游客身份不落库，反复进出会在 LiveKit 侧留下多条记录直到房间销毁。令牌由 <code>LIVEKIT_API_KEY</code> / <code>LIVEKIT_API_SECRET</code> 签名，未配置时接口返回 503，前端提示语音未就绪。</p><p><strong>客户端连接地址按三级优先级确定</strong>：管理端「基础设置 → 自定义 LiveKit 服务器地址」（如 <code>wss://livekit.example.com</code>，需与该服务器使用相同 API Key/Secret）→ 环境变量 <code>LIVEKIT_URL</code> → 从 <code>x-forwarded-host</code> / <code>x-forwarded-proto</code> 或 <code>Host</code> 头推导（HTTPS 页面自动得到 <code>wss://</code>，反代与 CDN 无需额外配置）。自动推导可避开容器 / 多网卡环境下探测到 Docker bridge 网段（<code>172.24.x.x</code>）的错误结果。</p><blockquote><p>新版 SDK 的 <code>token.toJwt()</code> 返回 Promise，必须 <code>await</code>；直接取同步值会序列化成 <code>[object Object]</code>，LiveKit 侧一律 401。</p></blockquote><h2 id="采集与发布" tabindex="-1">采集与发布 <a class="header-anchor" href="#采集与发布" aria-label="Permalink to &quot;采集与发布&quot;">​</a></h2><p>麦克风经 <code>getUserMedia</code> 采集，开启回声消除、降噪与自动增益，强制单声道，处理全在浏览器完成。音频进入 48kHz 的 <code>AudioContext</code> 节点链，<code>micGain</code> 控制输入音量，之后分流三路：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>麦克风 ──▶ micGain ──┬──▶ produceDest ──▶ 发布轨（送往 LiveKit）</span></span>
<span class="line"><span>                     ├──▶ monitorGain ──▶ ctx.destination（耳机反送）</span></span>
<span class="line"><span>                     └──▶ analyser（电平可视化）</span></span></code></pre></div><p>音频上下文<strong>不强制指定采样率</strong>：声卡硬件速率不同（蓝牙 HFP 常见 44.1kHz），强转 48kHz 会形成两级重采样，反送与发布出现周期性卡顿；LiveKit 对采集速率无要求。</p><table tabindex="0"><thead><tr><th>发布参数</th><th>取值</th><th>原因</th></tr></thead><tbody><tr><td><code>audioPreset</code></td><td><code>music</code></td><td>默认语音会议档约 24~32kbps 听感发闷；<code>music</code> 档为 48kbps 全带宽 Opus</td></tr><tr><td><code>dtx</code></td><td><code>false</code></td><td>关闭静默段传输，避免切换时音质劣化</td></tr><tr><td><code>red</code></td><td><code>true</code></td><td>保留 RED 冗余编码抵抗丢包</td></tr></tbody></table><p><strong>自闭麦</strong>只把发布轨 <code>enabled</code> 置 false，不发服务端请求；管理员禁言是另一套机制，见下文。</p><h2 id="收听与成员状态" tabindex="-1">收听与成员状态 <a class="header-anchor" href="#收听与成员状态" aria-label="Permalink to &quot;收听与成员状态&quot;">​</a></h2><p>远端音频轨由每个成员一个隐藏 <code>&lt;audio&gt;</code> 元素承载。成员列表在连接、断开、metadata 变更时刷新；每个成员另挂 <code>AnalyserNode</code>（<code>fftSize</code> 256、平滑系数 0.6）仅用于电平可视化。</p><p>音量分两层：全局音量 × 单成员音量，结果写入该成员 <code>&lt;audio&gt;.volume</code>。</p><p>反送按浏览器分别处理：Chrome 走媒体元素路径；Firefox 播放实时 <code>MediaStream</code> 有缓冲积压缺陷，改走 <code>AudioContext</code> 直连输出。反送默认关闭。</p><h2 id="禁言与踢出" tabindex="-1">禁言与踢出 <a class="header-anchor" href="#禁言与踢出" aria-label="Permalink to &quot;禁言与踢出&quot;">​</a></h2><p>管理动作走 REST，权限在服务端校验。禁言双通道强制，客户端无法绕过：</p><ol><li><strong>服务器侧静音</strong>：调用 <code>mutePublishedTrack</code> 静音目标成员已发布的所有音频轨。</li><li><strong>metadata 标记</strong>：参与者 metadata 写为 <code>{&quot;adminMuted&quot;: true}</code>，成员列表据此渲染 UI；被禁言端收到 <code>ParticipantMetadataChanged</code> 后锁定麦克风并提示，解禁自动恢复。</li></ol><p>踢出直接调用 <code>removeParticipant</code>，被踢端收到 <code>Disconnected</code> 后复位界面。</p><p>三处权限口径与房间管理一致：root、本人为主房主的 admin、房主、房管（<code>Room.moderators</code> 含该用户）。</p><table tabindex="0"><thead><tr><th>接口</th><th>动作</th><th>权限</th></tr></thead><tbody><tr><td><code>POST /api/voice/token</code></td><td>签发接入凭证</td><td>登录</td></tr><tr><td><code>POST /api/voice/mute</code></td><td>禁言 / 解禁对方麦克风</td><td>root / 房主 / 房管</td></tr><tr><td><code>POST /api/voice/kick</code></td><td>踢出语音</td><td>root / 房主 / 房管</td></tr></tbody></table><h2 id="信令反代" tabindex="-1">信令反代 <a class="header-anchor" href="#信令反代" aria-label="Permalink to &quot;信令反代&quot;">​</a></h2><p>两条通道都要代理，否则浏览器连不上：</p><ul><li><strong>HTTP</strong>：连接前先 <code>GET /rtc/v1/validate</code> 校验令牌，HTTPS 页面下不经代理会被混合内容策略拦截。</li><li><strong>WebSocket</strong>：后续信令帧经 <code>/rtc</code> 的 HTTP Upgrade 升级，升级后是不透明字节流，主后端只做裸 TCP 双向管道。</li></ul><p><code>upgrade</code> 处理器只放行两类路径：<code>/socket.io</code> 交给 Socket.IO，<code>/rtc</code> 隧道到 livekit-server，其余一律销毁。上游地址每次升级时从 <code>LIVEKIT_API_HOST</code> 解析（裸机 <code>127.0.0.1:3336</code>，compose 为 <code>livekit:3336</code>）。</p><h2 id="伴生服务的启动与降级" tabindex="-1">伴生服务的启动与降级 <a class="header-anchor" href="#伴生服务的启动与降级" aria-label="Permalink to &quot;伴生服务的启动与降级&quot;">​</a></h2><p>启动在数据库初始化之后触发，以 fire-and-forget 拉起子进程，不阻塞主服务。二进制缺失且下载失败期间 <code>/api/voice/token</code> 返回 503。</p><p>启动参数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>livekit-server --dev --bind :: --port 3336 --udp-port 3333 --keys &quot;&lt;key&gt;: &lt;secret&gt;&quot;</span></span></code></pre></div><p>ICE/TCP 端口由环境变量 <code>LIVEKIT_RTC_TCP_PORT</code>（默认 3337）下发，与 UDP 同时发布，不需要切模式。</p><ul><li><code>--bind ::</code> 双栈监听 IPv4 与 IPv6；绑 <code>0.0.0.0</code> 只会收到 IPv4，公网 IPv6 用户的媒体流无法建立。若环境无 IPv6 协议栈导致绑定 <code>::</code> 失败，自动回退 <code>0.0.0.0</code> 重试一次。</li><li><code>--keys</code> 冒号后必须带空格，缺空格时 livekit-server 直接退出。启动后轮询 3336 等待就绪，超时 15s 判定失败。</li><li>子进程注册 <code>exit</code>、<code>SIGINT</code>、<code>SIGTERM</code> 钩子，主进程退出时一并终止。</li></ul><p>启动时还有<strong>外网可达性自检</strong>：本机网卡全为私网地址（RFC1918 / 回环 / CGNAT）且未配置 <code>LIVEKIT_NODE_IP</code> 与 TURN 时，日志显式告警。典型场景是「局域网语音正常、外网连不上」——页面与信令经 CDN / 反代正常，但 WebRTC 媒体不经七层代理，属静默失败。日志给出三条路径：部署到有公网 IP 的主机并放行 3333/udp；用 frp 映射 3333/udp 并设 <code>LIVEKIT_NODE_IP</code>；或配置 TURN/TLS 三项并映射 3338/tcp。云服务器 EIP 场景网卡是私网但 STUN 可探测公网 IP，警告可忽略。</p><table tabindex="0"><thead><tr><th>变量</th><th>缺省值</th><th>作用</th></tr></thead><tbody><tr><td><code>LIVEKIT_API_KEY</code></td><td><code>devkey</code></td><td>令牌签名密钥</td></tr><tr><td><code>LIVEKIT_API_SECRET</code></td><td><code>zviewer-dev-secret</code></td><td>令牌签名密钥</td></tr><tr><td><code>LIVEKIT_API_HOST</code></td><td><code>http://127.0.0.1:3336</code></td><td>服务端 API 与信令反代的上游</td></tr><tr><td><code>LIVEKIT_BIND</code></td><td><code>::</code></td><td>伴生服务监听地址</td></tr><tr><td><code>LIVEKIT_RTC_TCP_PORT</code></td><td><code>3337</code></td><td>ICE/TCP 端口，<code>0</code> 关闭该通道</td></tr><tr><td><code>LIVEKIT_TURN_TLS_PORT</code></td><td><code>3338</code></td><td>TURN/TLS 端口，配齐域名与证书后启用</td></tr><tr><td><code>LIVEKIT_EXTERNAL</code></td><td>未设置</td><td>设为 <code>1</code> 跳过伴生服务，改用外置 LiveKit</td></tr></tbody></table><p>发行包不联网下载二进制，找不到伴生文件时只打印告警并给出重建指引，语音随之不可用。</p><h2 id="udp-与-tcp-同时发布" tabindex="-1">UDP 与 TCP 同时发布 <a class="header-anchor" href="#udp-与-tcp-同时发布" aria-label="Permalink to &quot;UDP 与 TCP 同时发布&quot;">​</a></h2><p>服务端同时发布 <code>3333/udp</code> 与 <code>3337/tcp</code>，浏览器 ICE 自动择优：UDP 直连 &gt; TCP 直连 &gt; TURN 中继。UDP 通道始终开启（LiveKit 不支持禁用 UDP 候选），TCP 是加开的直连通道，管理端没有开关；要彻底关掉需显式写 <code>LIVEKIT_RTC_TCP_PORT=0</code>。</p><p>TCP 直连与 TURN/TLS 中继解决同一类问题（UDP 被拦截），机制不同：</p><table tabindex="0"><thead><tr><th></th><th>ICE/TCP 3337</th><th>TURN/TLS 3338</th></tr></thead><tbody><tr><td>连接形态</td><td>浏览器与服务器<strong>直连</strong></td><td>经 TURN 服务器<strong>中继</strong></td></tr><tr><td>部署要求</td><td>无需域名与证书</td><td>需域名与正式证书（自签不被 WebRTC 信任）</td></tr><tr><td>启用方式</td><td>默认开启，端口置 <code>0</code> 关闭</td><td>配置 <code>LIVEKIT_TURN_DOMAIN</code> / <code>CERT</code> / <code>KEY</code></td></tr><tr><td>穿透能力</td><td>受限于网络是否放行 3337/tcp</td><td>更强（TLS 流量伪装为普通 HTTPS）</td></tr></tbody></table><p>二者可同时部署，客户端按连通性自动选择。语音面板实时显示当前协议徽标：前端周期轮询 <code>RTCPeerConnection.getStats()</code> 解析 ICE 实际选中的候选线路，跟随真实路径而非设置值。</p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>提示语音未就绪</td><td>伴生服务仍在下载 / 启动，或 API Key / Secret 未注入</td><td>查看日志 <code>[voice]</code> 段；Windows 包点房间里「下载语音聊天组件」，Linux 版确认包内有 <code>livekit-server</code></td></tr><tr><td>听不到别人声音</td><td>3333/udp 未放行</td><td>放行 UDP 3333；或放行 TCP 3337、配置 TURN/TLS</td></tr><tr><td>HTTPS 下报混合内容</td><td><code>/rtc</code> 未反代</td><td>确认反代把 <code>/rtc</code> 转发到 3333</td></tr><tr><td>连接后立刻断开</td><td>令牌序列化错误</td><td>检查是否 <code>await</code> 了 <code>token.toJwt()</code></td></tr><tr><td>只有 IPv6 用户连不上</td><td>监听绑到了 <code>0.0.0.0</code></td><td>确认 <code>LIVEKIT_BIND</code> 为 <code>::</code></td></tr><tr><td>局域网正常、外网连不上</td><td>网卡全私网且未配 <code>LIVEKIT_NODE_IP</code> 与 TURN</td><td>按启动日志三条路径处理</td></tr><tr><td>管理员禁言无效</td><td>目标已不在语音房间</td><td>接口在参与者列表中找不到目标时返回 404</td></tr></tbody></table><h2 id="常量速查" tabindex="-1">常量速查 <a class="header-anchor" href="#常量速查" aria-label="Permalink to &quot;常量速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>常量</th><th>值</th></tr></thead><tbody><tr><td>LiveKit 版本（开发模式自动下载）</td><td>v1.13.7</td></tr><tr><td>信令 / 媒体端口</td><td>3336 / 3333</td></tr><tr><td>ICE/TCP 端口</td><td>3337</td></tr><tr><td>TURN/TLS 端口</td><td>3338</td></tr><tr><td>就绪等待超时</td><td>15s</td></tr><tr><td>发布编码档</td><td><code>music</code>（48kbps Opus），<code>dtx: false</code>，<code>red: true</code></td></tr><tr><td>电平分析 fftSize / 平滑系数</td><td>256 / 0.6</td></tr></tbody></table>`,55)])])}const b=d(a,[["render",r]]);export{T as __pageData,b as default};
